package com.oracle.observability.kafka.connect;

import static org.junit.jupiter.api.Assertions.*;

import java.util.ServiceLoader;
import org.apache.kafka.common.config.ConfigException;
import org.apache.kafka.connect.connector.Connector;
import org.junit.jupiter.api.Test;

class OracleObservabilitySinkConnectorTest {
    @Test
    void producesIndependentTaskConfigsAndCanBeDiscovered() {
        var connector = new OracleObservabilitySinkConnector();
        connector.start(TestFixtures.properties());
        var tasks = connector.taskConfigs(2);
        assertEquals(2, tasks.size());
        tasks.get(0).put(OracleObservabilitySinkConfig.REGION, "other");
        assertEquals("us-phoenix-1", tasks.get(1).get(OracleObservabilitySinkConfig.REGION));
        assertEquals(OracleObservabilitySinkTask.class, connector.taskClass());
        assertTrue(ServiceLoader.load(Connector.class).stream()
                .anyMatch(provider -> provider.type().equals(OracleObservabilitySinkConnector.class)));
        connector.stop();
    }

    @Test
    void rejectsMissingBlankAndUnsafeConfiguration() {
        for (String key : new String[] {OracleObservabilitySinkConfig.REGION,
                OracleObservabilitySinkConfig.NAMESPACE, OracleObservabilitySinkConfig.CONFIG_FILE,
                OracleObservabilitySinkConfig.LOG_GROUP_ID, OracleObservabilitySinkConfig.LOG_SOURCE_NAME}) {
            var missing = TestFixtures.properties();
            missing.remove(key);
            assertThrows(ConfigException.class, () -> new OracleObservabilitySinkConfig(missing));
            missing.put(key, "  ");
            assertThrows(ConfigException.class, () -> new OracleObservabilitySinkConfig(missing));
        }
        var byteProps = TestFixtures.properties();
        byteProps.put(OracleObservabilitySinkConfig.MAX_BYTES, "1048577");
        assertThrows(ConfigException.class, () -> new OracleObservabilitySinkConfig(byteProps));
        var entityProps = TestFixtures.properties();
        entityProps.put(OracleObservabilitySinkConfig.ENTITY_TYPE, "Host (Linux)");
        assertThrows(ConfigException.class, () -> new OracleObservabilitySinkConfig(entityProps));
    }

    @Test
    void rejectsInvalidRetryAndTimeoutRelationships() {
        var retry = TestFixtures.properties();
        retry.put(OracleObservabilitySinkConfig.RETRY_MAX_MS, "1");
        assertThrows(ConfigException.class, () -> new OracleObservabilitySinkConfig(retry));
        var budget = TestFixtures.properties();
        budget.put(OracleObservabilitySinkConfig.PUT_BUDGET_MS, "1");
        assertThrows(ConfigException.class, () -> new OracleObservabilitySinkConfig(budget));
    }
}
